input.command:
pr_number=102
owner=135yshr; repo=documents
gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr_number" -f query='query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      title
      reviewThreads(first:100) {
        pageInfo { hasNextPage endCursor }
        nodes {
          isResolved
          isOutdated
          comments(first:1) {
            nodes { databaseId body path line startLine originalLine author { login } }
          }
        }
      }
    }
  }
}' > "$TMPDIR/threads.json" 2>&1 && jq '.data.repository.pullRequest.reviewThreads.nodes | length' "$TMPDIR/threads.json"; jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false and .isOutdated==false) | .comments.nodes[0] | "\(.author.login) | \(.path):\(.line // .originalLine)"' "$TMPDIR/threads.json"

gh api graphql -F owner=135yshr -F repo=documents -F pr=102 -f query='query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      reviewThreads(first:100) {
        nodes {
          isResolved
          isOutdated
          comments(first:1) {
            nodes { databaseId body path line startLine originalLine author { login } }
          }
        }
      }
    }
  }
}' | jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false and .isOutdated==false) | .comments.nodes[0] | "=== \(.path):\(.line // .originalLine) (id \(.databaseId)) ===\n\(.body)\n"'
